"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
import heapq

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def _dijkstra(graph: WeightedGraph, source: int, target: int = None, k_early: int = None) -> Tuple[Dict[int, float], Dict[int, Optional[int]]]:
    dist = {source: 0.0}
    prev: Dict[int, Optional[int]] = {source: None}
    heap = [(0.0, source)]
    visited = set()
    count = 0

    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        count += 1

        if target is not None and u == target:
            break
        if k_early is not None and count > k_early:
            break

        for v, w in graph.adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    return dist, prev


def _build_path(prev: Dict[int, Optional[int]], target: int) -> List[int]:
    path = []
    cur = target
    while cur is not None:
        path.append(cur)
        cur = prev.get(cur)
    path.reverse()
    return path


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []
    dist, prev = _dijkstra(graph, source, target=target)
    if target not in dist:
        return None, []
    return dist[target], _build_path(prev, target)


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    result = {}
    if source not in graph.nodes:
        return result
    dist, prev = _dijkstra(graph, source)
    for node in dist:
        result[node] = (dist[node], _build_path(prev, node))
    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    if source not in graph.nodes:
        return []
    dist, _ = _dijkstra(graph, source, k_early=k + 1)
    items = [(n, d) for n, d in dist.items() if n != source]
    items.sort(key=lambda x: x[1])
    return items[:k]


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False
    # BFS O(V+E)
    visited = set()
    queue = [source]
    visited.add(source)
    while queue:
        u = queue.pop()
        if u == target:
            return True
        for v, _ in graph.adj.get(u, []):
            if v not in visited:
                visited.add(v)
                queue.append(v)
    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    # Build undirected adjacency list
    undirected: Dict[int, List[int]] = {n: [] for n in graph.nodes}
    for e in graph._edges:
        undirected[e.src].append(e.dst)
        undirected[e.dst].append(e.src)

    visited = set()
    components = []
    for node in graph.nodes:
        if node in visited:
            continue
        comp = set()
        stack = [node]
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            comp.add(u)
            for v in undirected[u]:
                if v not in visited:
                    stack.append(v)
        components.append(comp)
    return components
